#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

#define MAXN 200005

using ll = long long;

int n;

struct Rng
{
    ll l, r;
} a[MAXN], b[MAXN];

ll c[MAXN << 1];

vector<Rng> ad[MAXN << 1], de[MAXN << 1];

int cal(ll a, ll b, ll c)
{
    ll m = (a + b + c + 1) / 2;
    if (a >= m)
    {
        return -1;
    }
    if (a + b >= m)
    {
        return 0;
    }
    return 1;
}

bool calc(Rng l, ll m, Rng r)
{
    int s = cal(l.l, m, r.r), t = cal(l.r, m, r.l);
    return m && (s == 0 || t == 0 || s != t);
}

void solve()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        cin >> a[i].l >> a[i].r >> b[i].l >> b[i].r;
        c[2 * i - 1] = b[i].l;
        c[2 * i] = b[i].r + 1;
    }
    sort(c + 1, c + 2 * n + 1);
    int idx = unique(c + 1, c + 2 * n + 1) - c - 1;
    Rng l{0, 0}, r{0, 0};
    ll m = 0;
    for (int i = 1; i <= n; i++)
    {
        b[i].l = lower_bound(c + 1, c + idx + 1, b[i].l) - c;
        b[i].r = lower_bound(c + 1, c + idx + 1, b[i].r + 1) - c;
        ad[b[i].l].push_back(a[i]);
        de[b[i].r].push_back(a[i]);
        r.l += a[i].l, r.r += a[i].r;
    }
    ll res = 0;
    for (int i = 1; i <= idx; i++)
    {
        for (auto [u, v] : ad[i])
        {
            m += v;
            r.l -= u, r.r -= v;
        }
        for (auto [u, v] : de[i])
        {
            m -= v;
            l.l += u, l.r += v;
        }
        if (calc(l, m, r))
        {
            res += c[i + 1] - c[i];
        }
        ad[i].clear();
        de[i].clear();
    }
    cout << res << endl;
}

int main()
{
    int t;
    cin >> t >> t;
    while (t--)
    {
        solve();
    }
    return 0;
}

#include<bits/stdc++.h>
#define int long long
using namespace std;
const int N=2e5+10;
int c,T,n,l[N],r[N],ll[N],rr[N];
int check1(int x){
    int L=0,R=0;
    for(int i=1;i<=n;i++){
        if(ll[i]>x)R+=l[i];
        else L+=r[i];
    }
    if(L>=R)return 1;
    return 0;
}
int check2(int x){
    int L=0,R=0;
    for(int i=1;i<=n;i++){
        if(rr[i]<x)L+=l[i];
        else R+=r[i];
    }
    if(R>L)return 1;
    return 0;
}
struct node{
    int l,r;
}a[N];
bool cmp(node a,node b){
    if(a.l==b.l)return a.r<b.r;
    return a.l<b.l;
}
signed main(){
    cin>>c>>T;
    while(T--){
        cin>>n;
        int L=1,R,mx=0,cnt=0;
        for(int i=1;i<=n;i++){
            scanf("%lld%lld%lld%lld",&l[i],&r[i],&ll[i],&rr[i]);
            mx=max(mx,rr[i]);
        }
        int ans1,ans2;
        R=mx;
        while(L<=R){
            int mid=L+R>>1;
            if(check1(mid)){
                ans1=mid;
                R=mid-1;
            }
            else L=mid+1;
        }
        L=1,R=mx;
        while(L<=R){
            int mid=L+R>>1;
            if(check2(mid)){
                ans2=mid;
                L=mid+1;
            }
            else R=mid-1;
        }
        for(int i=1;i<=n;i++){
            if(rr[i]<ans1||ll[i]>ans2)continue;
            ll[i]=max(ll[i],ans1);
            rr[i]=min(rr[i],ans2);
            a[++cnt]={ll[i],rr[i]};
        }
        sort(a+1,a+cnt+1,cmp);
        int ans=0,lst=0;
        for(int i=1;i<=cnt;i++){
            if(a[i].l>lst){
                lst=a[i].r;
                ans+=a[i].r-a[i].l+1;
            }
            else{
                if(a[i].r>lst){
                    ans+=a[i].r-lst;
                    lst=a[i].r;
                }
            }
        }
        cout<<ans<<'\n';
    }
    return 0;
}
